package com.vaultor.vaultor;
import com.vaultor.vaultor.service.*;import com.vaultor.vaultor.repository.*;import com.vaultor.vaultor.host.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.*;import org.springframework.mock.web.MockMultipartFile;import tools.jackson.databind.ObjectMapper;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
class CompanionExportTest {
 static final Path DATA;static{try{DATA=Files.createTempDirectory("vaultor-r8-export-");}catch(Exception e){throw new ExceptionInInitializerError(e);}}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry p){p.add("app.host.network-port",()->"0");p.add("app.host.path",()->DATA.resolve("host").toString());p.add("spring.datasource.url",()->"jdbc:sqlite:"+DATA.resolve("app.db"));p.add("app.storage.path",()->DATA.resolve("files").toString());}
 @Autowired OrganizationService organization;@Autowired TransferService transfers;@Autowired ResourceService notes;@Autowired ResourceRepository resources;@Autowired WorkspaceIdentityService identity;@Autowired CompanionImports imports;@Autowired ObjectMapper json;
 String id(){return UUID.randomUUID().toString();}
 TransferService.ExportReceipt start(String id,TransferService.ExportRequest r,String device)throws Exception {for(int n=0;n<500;n++)try{return transfers.prepareCompanionExport(id,r,device);}catch(org.springframework.web.server.ResponseStatusException e){if(e.getStatusCode().value()!=409)throw e;Thread.sleep(20);}throw new AssertionError("Preparation did not settle");}
 TransferService.ExportReceipt await(String id,String generation,String device)throws Exception {for(int n=0;n<500;n++){try{var r=transfers.companionExport(id,generation,device);if(Set.of("SUCCEEDED","FAILED").contains(r.operation().status()))return r;}catch(org.springframework.web.server.ResponseStatusException e){if(e.getStatusCode().value()!=409)throw e;}Thread.sleep(20);}throw new AssertionError("Export did not settle");}
 String document(String link){return "{\"type\":\"doc\",\"content\":[{\"type\":\"paragraph\",\"content\":[{\"type\":\"resourceLink\",\"attrs\":{\"resourceId\":\""+link+"\",\"label\":\"Target\"}}]}]}";}
 @Test void fullExportReplaysExactIdentityAndRejectsChangedDeviceIntentOrGeneration()throws Exception {notes.createNote("Export full","{\"type\":\"doc\",\"content\":[{\"type\":\"paragraph\"}]}");String id=id(),generation=identity.current().generation();var request=new TransferService.ExportRequest(generation,"workspace",List.of(),0,"zip");start(id,request,"device");var receipt=await(id,generation,"device");assertEquals("SUCCEEDED",receipt.operation().status());assertTrue(receipt.bytes()>0);assertEquals(64,receipt.sha256().length());assertEquals(receipt,start(id,request,"device"));assertThrows(Exception.class,()->start(id,request,"other"));assertThrows(Exception.class,()->start(id,new TransferService.ExportRequest(generation,"workspace",List.of(),1,"zip"),"device"));assertThrows(Exception.class,()->transfers.companionExport(id,id(),"device"));}
 @Test void partialPreservesOriginalsAndMissingLinksCannotBindExistingDestinationIds()throws Exception {var target=notes.createNote("Existing unrelated namespace","{\"type\":\"doc\",\"content\":[]}");var root=notes.createNote("Partial root",document(target.getId()));var f=new MockMultipartFile("file","original.md","text/plain","# Original\r\nExact raw bytes".getBytes());String converted=id();imports.create(converted,new CompanionImports.Intent(identity.current().generation(),"original.md","text/plain",CompanionImports.hash(f.getInputStream()),f.getSize(),"markdown",null),f,"device");String operation=id(),generation=identity.current().generation();var request=new TransferService.ExportRequest(generation,"resources",List.of(root.getId(),converted),0,"partial");start(operation,request,"device");var result=await(operation,generation,"device");assertEquals("SUCCEEDED",result.operation().status());assertEquals(2,result.coverage().get("inventory").size());assertEquals(target.getId(),result.coverage().get("omissions").get(0).get("id").asText());byte[] archive=Files.readAllBytes(transfers.download(operation));try(var zip=new java.util.zip.ZipInputStream(new java.io.ByteArrayInputStream(archive))){java.util.zip.ZipEntry e;boolean provenance=false,manifest=false;while((e=zip.getNextEntry())!=null){if(e.getName().equals("manifest.json")){manifest=true;assertEquals(6,json.readTree(zip.readAllBytes()).get("version").asInt());}if(e.getName().equals("originals/"+converted)){provenance=true;assertArrayEquals(f.getBytes(),zip.readAllBytes());}}assertTrue(provenance&&manifest);}
  var preview=transfers.preview(new MockMultipartFile("file","partial.zip","application/zip",archive));assertTrue(preview.warnings().stream().anyMatch(w->w.startsWith("Partial package")));assertThrows(Exception.class,()->transfers.commit(preview.operation().id(),"replace"));transfers.commit(preview.operation().id(),"merge");for(int n=0;n<500;n++){try{if(transfers.get(preview.operation().id()).status().equals("SUCCEEDED"))break;}catch(org.springframework.web.server.ResponseStatusException busy){}Thread.sleep(20);}var copy=resources.findAll().stream().filter(r->r.getTitle().equals("Partial root")&&!r.getId().equals(root.getId())).findFirst().orElseThrow();assertFalse(copy.getContent().contains(target.getId()));assertEquals(document(target.getId()),resources.findById(root.getId()).orElseThrow().getContent());var originalCopy=resources.findAll().stream().filter(r->r.getImportOriginalPath()!=null&&!r.getId().equals(converted)).findFirst().orElseThrow();assertArrayEquals(f.getBytes(),Files.readAllBytes(imports.original(originalCopy.getId())));
 }
 @Test void cyclesDeduplicateAndConnectedNoteConversionRemainsAvailable()throws Exception {var a=notes.createNote("Cycle A","{\"type\":\"doc\",\"content\":[]}");var b=notes.createNote("Cycle B",document(a.getId()));var old=resources.findById(a.getId()).orElseThrow();notes.updateNote(a.getId(),a.getTitle(),document(b.getId()),'"'+old.getRevision()+'"');String generation=identity.current().generation(),id=id();start(id,new TransferService.ExportRequest(generation,"resources",List.of(a.getId()),3,"partial"),"device");assertEquals(2,await(id,generation,"device").coverage().get("inventory").size());String noteExport=id();start(noteExport,new TransferService.ExportRequest(generation,"note",List.of(a.getId()),0,"md"),"device");assertEquals("SUCCEEDED",await(noteExport,generation,"device").operation().status());}
 @Test void invalidBoundsAndForeignOperationCannotAcquireReceipt()throws Exception {String generation=identity.current().generation();assertThrows(Exception.class,()->start(id(),new TransferService.ExportRequest(generation,"resources",List.of(id()),4,"partial"),"device"));var ordinary=transfers.export("workspace","zip");assertThrows(Exception.class,()->start(ordinary.id(),new TransferService.ExportRequest(generation,"workspace",List.of(),0,"zip"),"device"));}
 @Test void nestedPartialRetainsEmptyAncestorsAndUsesSchemaEight()throws Exception {
  var parent=organization.createOnce(id(),new OrganizationService.CreationInput("Partial hierarchy root",List.of()));var child=organization.createOnce(id(),new OrganizationService.CreationInput("Partial hierarchy child",List.of(),parent.id()));
  var note=notes.createNote("Nested partial","{\"type\":\"doc\",\"content\":[]}");organization.bulk(new OrganizationService.BulkInput(List.of(note.getId()),"collection",child.id(),"add"));
  String operation=id(),generation=identity.current().generation();start(operation,new TransferService.ExportRequest(generation,"resources",List.of(note.getId()),0,"partial"),"device");assertEquals("SUCCEEDED",await(operation,generation,"device").operation().status());
  byte[] archive=Files.readAllBytes(transfers.download(operation));try(var zip=new java.util.zip.ZipInputStream(new java.io.ByteArrayInputStream(archive))){java.util.zip.ZipEntry entry;boolean manifest=false,workspace=false;while((entry=zip.getNextEntry())!=null){if(entry.getName().equals("manifest.json")){assertEquals(8,json.readTree(zip.readAllBytes()).get("version").asInt());manifest=true;}if(entry.getName().equals("workspace.json")){var collections=json.readTree(zip.readAllBytes()).get("organization").get("collections");assertEquals(2,collections.size());for(var c:collections)if(c.get("id").asText().equals(parent.id()))assertEquals(0,c.get("resources").size());else assertEquals(parent.id(),c.get("parentId").asText());workspace=true;}}assertTrue(manifest&&workspace);}
  assertTrue(transfers.preview(new MockMultipartFile("file",archive)).partial());
 }

}
